from autor import Lectie, Expeditie, Unitate, grafic

REF = "Manual Art Klett, clasa a VI-a (manuale.edu.ro), lecția „{}”"
S_8MLD = ["ONU (UN DESA) – „World population to reach 8 billion on 15 November 2022”", "UNFPA – Day of Eight Billion"]
S_INDIA = ["UN DESA – Policy Brief nr. 153: India overtakes China as the world's most populous country (aprilie 2023)", "BBC News, 24.04.2023 – India to overtake China's population"]
S_ORASE = ["ONU (UN DESA) – World Urbanization Prospects 2025", "Al Jazeera, 26.11.2025 – Jakarta now the world's largest city, Tokyo falls to third"]
S_URBAN = ["ONU (UN DESA) – World Urbanization Prospects 2025", "Banca Mondială – Urban population (% of total)"]
S_EVOL = ["ONU (UN DESA) – World Population Prospects 2024", "Our World in Data – Population growth"]


def unitate():
    # ================================================================ S6 Populația Terrei
    P = Lectie(6, "VI-S06-populatia-terrei-evolutia-numerica", "Populația Terrei",
               "Câți oameni trăiesc acum pe Pământ și unde locuiesc cei mai mulți?",
               [("Evoluția numerică", "Timp de mii de ani, populația a crescut foarte încet. După anul 1800, odată cu progresul medicinei, al agriculturii și al igienei, a început să crească foarte repede.\nPopulația Pământului a ajuns la 8 miliarde de oameni pe 15 noiembrie 2022, după estimările ONU. Din 2023, India a depășit China și este țara cu cea mai numeroasă populație."),
                ("Bilanțul natural și densitatea", "Natalitatea arată câți copii se nasc, iar mortalitatea câți oameni mor, la 1 000 de locuitori, într-un an. Diferența dintre ele se numește spor (bilanț) natural.\nDensitatea populației arată câți locuitori trăiesc, în medie, pe 1 km²: numărul locuitorilor împărțit la suprafață."),
                ("Răspândire, diversitate, mobilitate", "Oamenii trăiesc mai ales în câmpii, pe văile râurilor și pe țărmuri, unde clima e blândă și există apă. Sunt puțin locuite deșerturile, zonele polare, munții înalți și pădurile ecuatoriale.\nOamenii diferă prin limbă, religie, obiceiuri, culoarea pielii – aceasta e diversitatea umană.\nMigrația înseamnă mutarea oamenilor dintr-un loc în altul, temporar sau definitiv: pentru muncă, studii, siguranță sau familie.")],
               stiaica="Peste o treime din populația lumii trăiește în doar două țări: India și China.",
               ref=REF.format("Populația Terrei"))
    P.a(1, "3.1", "Ce prag a atins populația Pământului în noiembrie 2022, după ONU?", "8 miliarde", ["1 miliard", "800 de milioane", "80 de miliarde"], "ONU a anunțat atingerea pragului de 8 miliarde pe 15 noiembrie 2022.", surse=S_8MLD)
    P.a(2, "3.1", "Ce țară are cea mai numeroasă populație, din 2023?", "India", ["China", "SUA", "Rusia"], "India a depășit China în 2023, după estimările ONU.", surse=S_INDIA)
    P.a(1, "1.1", "Ce arată natalitatea?", "câți copii se nasc la 1 000 de locuitori, într-un an", ["câți oameni mor", "câți oameni pleacă", "suprafața țării"], "Natalitatea măsoară nașterile.")
    P.a(1, "1.1", "Ce arată mortalitatea?", "câți oameni mor la 1 000 de locuitori, într-un an", ["câți copii se nasc", "câți turiști vin", "câte orașe sunt"], "Mortalitatea măsoară decesele.")
    P.a(2, "1.1", "Ce este sporul natural?", "diferența dintre natalitate și mortalitate", ["suma nașterilor și a deceselor", "numărul de migranți", "numărul de orașe"], "Dacă se nasc mai mulți decât mor, sporul e pozitiv.")
    P.a(2, "3.2", "Într-o țară, natalitatea e 9‰, iar mortalitatea 12‰. Ce spor natural are?", "−3‰ (negativ: populația scade natural)", ["+21‰", "+3‰", "0‰"], "9 − 12 = −3. Sporul negativ înseamnă că mor mai mulți decât se nasc.")
    P.a(2, "1.1", "Ce este densitatea populației?", "numărul mediu de locuitori pe 1 km²", ["numărul de orașe", "înălțimea clădirilor", "numărul de copii dintr-o familie"], "Densitatea = populație : suprafață.")
    P.a(3, "3.2", "O regiune are 200 000 de locuitori și 1 000 km². Ce densitate are?", "200 loc./km²", ["2 000 loc./km²", "20 loc./km²", "200 000 loc./km²"], "200 000 : 1 000 = 200.")
    P.a(3, "3.2", "Un oraș are 30 000 de locuitori pe 15 km². Ce densitate are?", "2 000 loc./km²", ["200 loc./km²", "450 000 loc./km²", "15 loc./km²"], "30 000 : 15 = 2 000.")
    P.g(2, "2.3 4.1", "Graficul arată evoluția populației lumii (valori rotunjite). Ce observi?", grafic("profil", "Populația lumii", [("1800", 1), ("1900", 1.6), ("1950", 2.5), ("2000", 6.1), ("2022", 8)], "miliarde", "ONU – World Population Prospects 2024"), "populația a crescut foarte repede după 1950", ["populația a scăzut", "populația a rămas aceeași", "populația a crescut doar înainte de 1800"], "De la 2,5 miliarde în 1950 la 8 miliarde în 2022.", surse=S_EVOL)
    P.a(2, "3.2", "De ce a crescut populația foarte repede după 1800?", "datorită progresului medicinei, al agriculturii și al igienei", ["pentru că au dispărut orașele", "pentru că s-au oprit nașterile", "pentru că s-a răcit clima"], "Au scăzut bolile și foametea, deci mortalitatea.")
    P.s(2, "3.2", "Asociază zona cu cât de populată e.", [("Câmpia Gangelui (India)", "foarte populată"), ("Sahara", "foarte slab populată"), ("Antarctica", "fără populație permanentă"), ("Europa de Vest", "dens populată")], "Clima, apa și relieful decid unde trăiesc oamenii.")
    P.a(2, "3.2", "De ce deșerturile sunt slab populate?", "pentru că lipsește apa", ["pentru că sunt prea mici", "pentru că sunt prea verzi", "pentru că plouă mult"], "Fără apă nu se pot practica agricultura și viața obișnuită.")
    P.a(2, "3.2", "Unde trăiesc cei mai mulți oameni?", "în câmpii, pe văile râurilor și pe țărmuri", ["pe vârfuri de munți", "în deșerturi", "în zonele polare"], "Acolo sunt apă, soluri fertile și transport ușor.")
    P.p(2, "2.1", "Atinge pe hartă India, țara cu cea mai numeroasă populație.", "lume", 21, 78, "India", 900, "India e în sudul Asiei.", surse=S_INDIA)
    P.p(2, "2.1", "Atinge pe hartă China.", "lume", 35, 103, "China", 1300, "China e în estul Asiei.")
    P.d(3, "2.1", "Ce regiune foarte slab populată e marcată pe hartă?", "lume", 23, 12, "Sahara", ["Câmpia Gangelui", "Europa de Vest", "Delta Nilului"], "Sahara e cel mai mare deșert fierbinte, foarte slab populat.")
    P.a(2, "1.1", "Ce înseamnă migrație?", "mutarea oamenilor dintr-un loc în altul", ["creșterea natalității", "construirea de orașe", "schimbarea climei"], "Migrația poate fi internă sau externă, temporară sau definitivă.")
    P.s(2, "1.1", "Asociază tipul de migrație cu exemplul.", [("migrație internă", "o familie se mută de la sat la oraș, în aceeași țară"), ("emigrare", "cineva pleacă din țara lui să trăiască în alta"), ("imigrare", "cineva vine să trăiască în țara noastră"), ("migrație temporară", "cineva lucrează un sezon în străinătate și revine")], "Migrația are mai multe forme.")
    P.a(2, "1.2", "De ce migrează oamenii?", "pentru muncă, studii, siguranță sau ca să fie lângă familie", ["doar pentru vacanță", "fără niciun motiv", "pentru că așa e legea"], "Motivele pot fi economice, sociale sau de siguranță.")
    P.a(2, "3.3", "Ce înseamnă diversitate umană?", "oamenii diferă prin limbă, religie, obiceiuri, aspect fizic", ["toți oamenii vorbesc aceeași limbă", "oamenii trăiesc doar la oraș", "oamenii au aceeași religie"], "Diversitatea e o bogăție a umanității.")
    P.adev(2, "3.2", "Dacă natalitatea e mai mare decât mortalitatea, populația crește natural.", True, "Adevărat: sporul natural e pozitiv.")
    P.adev(2, "1.2", "Oamenii sunt răspândiți uniform pe tot uscatul.", False, "Fals: unele regiuni sunt foarte populate, altele aproape goale.")
    P.l(2, "1.1", "Completează.", "Numărul nașterilor la 1 000 de locuitori se numește [natalitate], iar numărul deceselor se numește [mortalitate].", ["densitate", "migrație"], "Natalitate, mortalitate.")
    P.l(2, "1.1", "Completează.", "Densitatea populației se calculează împărțind numărul [locuitorilor] la [suprafață].", ["orașelor", "altitudine"], "Locuitori : suprafață.")
    P.g(3, "2.3 4.1", "Graficul arată natalitatea și mortalitatea în trei țări imaginare (‰). În care populația scade natural?", grafic("bare", "Spor natural (natalitate − mortalitate), țări imaginare", [("țara A", 12), ("țara B", -4), ("țara C", 2)], "‰"), "în țara B", ["în țara A", "în țara C", "în toate"], "Doar țara B are spor natural negativ.")
    P.a(3, "4.3", "Compară două țări: A are 100 loc./km², B are 10 loc./km². Ce poți spune?", "țara A e de 10 ori mai dens populată decât B", ["țara B are mai mulți locuitori sigur", "sunt la fel", "țara A e mai mare"], "Densitatea compară cât de „aglomerat” e un teritoriu, nu mărimea lui.")
    P.a(2, "3.4", "Cum se numește numărarea oficială a populației unei țări?", "recensământ", ["referendum", "inventar", "sondaj de opinie"], "În România, ultimul recensământ s-a făcut în 2021–2022, de către INS.")
    P.a(3, "1.2", "De ce în multe țări europene populația îmbătrânește?", "pentru că se nasc puțini copii și oamenii trăiesc mai mult", ["pentru că se nasc foarte mulți copii", "pentru că nu există spitale", "pentru că toți tinerii vin în Europa"], "Natalitatea scăzută și speranța de viață mare cresc proporția vârstnicilor.")
    P.a(2, "4.2", "Ce continent nu are populație permanentă?", "Antarctica", ["Australia", "Europa", "Africa"], "În Antarctica trăiesc doar cercetători, temporar.")

    # ================================================================ S7 Așezările omenești
    A = Lectie(6, "VI-S07-asezarile-omenesti-forme-locuire", "Așezările omenești",
               "Prin ce se deosebește un sat de un oraș?",
               [("Ce sunt așezările", "Așezările omenești sunt locurile în care oamenii trăiesc permanent, cu locuințe, drumuri, școli, magazine. Ele sunt de două feluri: rurale (satele) și urbane (orașele).\nAșezările s-au format unde existau apă, sol fertil, adăpost, drumuri comerciale sau resurse."),
                ("Satele", "Satele au puțini locuitori, iar mulți dintre ei lucrează în agricultură, creșterea animalelor sau în exploatarea pădurilor.\nDupă formă, satele pot fi: adunate (casele strânse, în câmpie), risipite (casele împrăștiate, la munte), răsfirate (casele în grupuri, pe dealuri) sau liniare (de-a lungul unui drum sau al unei văi)."),
                ("Orașele", "Orașele au mulți locuitori, care lucrează mai ales în industrie și servicii. Au clădiri înalte, rețele de transport, universități, spitale.\nUrbanizarea este creșterea numărului și a populației orașelor. Astăzi, mai mult de jumătate din oameni trăiesc la oraș. Orașele foarte mari, cu peste 10 milioane de locuitori, se numesc megalopolisuri sau megaorașe.")],
               stiaica="După un raport ONU din 2025, cea mai populată aglomerare urbană din lume e Jakarta (Indonezia), cu aproximativ 42 de milioane de locuitori, urmată de Dhaka și Tokyo.",
               ref=REF.format("Așezările omenești – forme de locuire"))
    A.a(1, "1.1", "Ce sunt așezările omenești?", "locurile în care oamenii trăiesc permanent", ["locurile de vacanță", "pădurile", "câmpurile cultivate"], "Satele și orașele sunt așezări omenești.")
    A.s(1, "1.1", "Asociază tipul de așezare cu caracteristica.", [("satul", "puțini locuitori, multe ocupații agricole"), ("orașul", "mulți locuitori, industrie și servicii"), ("capitala", "sediul conducerii țării"), ("megaorașul", "peste 10 milioane de locuitori")], "Așezări rurale și urbane.")
    A.a(2, "1.2", "Ce ocupație e mai frecventă la sat decât la oraș?", "agricultura", ["lucrul într-o bancă", "lucrul într-un aeroport", "lucrul la metrou"], "Satele sunt legate de pământ și animale.")
    A.a(2, "1.2", "Unde s-au format de obicei primele așezări?", "lângă apă, pe soluri fertile, la adăpost", ["în deșert, departe de apă", "pe ghețari", "pe vârfuri de munte"], "Apa și hrana erau esențiale.")
    A.s(2, "3.2", "Asociază forma satului cu relieful în care apare des.", [("sat adunat", "câmpie"), ("sat risipit", "munte"), ("sat răsfirat", "deal"), ("sat liniar", "de-a lungul unei văi sau al unui drum")], "Relieful influențează forma satelor.")
    A.a(2, "1.1", "Ce este urbanizarea?", "creșterea numărului de orașe și a populației care trăiește în ele", ["mutarea oamenilor la sat", "construirea de ferme", "tăierea pădurilor"], "Urban = de oraș.")
    A.a(2, "3.1", "Ce parte din populația lumii trăiește astăzi la oraș?", "mai mult de jumătate", ["o zecime", "un sfert", "aproape nimeni"], "Peste jumătate din oameni trăiesc în orașe, după ONU.", surse=S_URBAN)
    A.a(2, "3.1", "Care e cea mai populată aglomerare urbană din lume, după raportul ONU din 2025?", "Jakarta (Indonezia)", ["București", "Paris", "New York"], "Jakarta, cu aproximativ 42 de milioane de locuitori, urmată de Dhaka și Tokyo.", surse=S_ORASE)
    A.o(3, "4.3", "Ordonează aglomerările urbane după populație, după raportul ONU din 2025.", ["Jakarta", "Dhaka", "Tokyo"], "De la cea mai populată", "Jakarta, Dhaka, Tokyo.", surse=S_ORASE)
    A.p(2, "2.1", "Atinge pe hartă Jakarta, cea mai populată aglomerare urbană.", "lume", -6.2, 106.8, "Jakarta", 700, "Jakarta e pe insula Java, în Indonezia.", surse=S_ORASE)
    A.p(2, "2.1", "Atinge pe hartă Tokyo.", "lume", 35.7, 139.7, "Tokyo", 600, "Tokyo e capitala Japoniei.")
    A.p(3, "2.1", "Atinge pe hartă New York.", "lume", 40.7, -74, "New York", 600, "New York e pe coasta de est a SUA.")
    A.a(2, "1.2", "Ce funcție are un oraș-port, ca Constanța?", "transport și comerț pe mare", ["exploatarea cărbunelui", "agricultura montană", "sporturile de iarnă"], "Portul Constanța e cel mai mare de la Marea Neagră.")
    A.s(2, "1.2", "Asociază orașul cu funcția lui principală.", [("Constanța", "port maritim"), ("Sinaia", "stațiune turistică montană"), ("Petroșani", "centru minier"), ("București", "capitală, centru administrativ")], "Orașele au funcții diferite.")
    A.a(2, "3.2", "Ce probleme au orașele foarte mari?", "aglomerație în trafic, poluare, locuințe scumpe", ["lipsa totală a școlilor", "prea puțini oameni", "prea multe ferme"], "Creșterea rapidă a orașelor aduce probleme.")
    A.a(2, "3.2", "De ce mulți tineri se mută de la sat la oraș?", "pentru locuri de muncă, școli și servicii", ["pentru că la oraș e aer mai curat", "pentru că la oraș sunt mai multe animale", "pentru că satele dispar peste noapte"], "Orașele oferă mai multe oportunități.")
    A.adev(2, "1.2", "Toate satele au aceeași formă, indiferent de relief.", False, "Fals: la munte casele sunt risipite; la câmpie, adunate.")
    A.adev(2, "3.2", "În orașe, majoritatea oamenilor lucrează în industrie și servicii.", True, "Adevărat: agricultura e mai ales la sat.")
    A.l(2, "1.1", "Completează.", "Satele sunt așezări [rurale], iar orașele sunt așezări [urbane].", ["montane", "maritime"], "Rural – sat; urban – oraș.")
    A.l(2, "1.1", "Completează.", "Creșterea populației orașelor se numește [urbanizare]; orașele cu peste 10 milioane de locuitori se numesc [megaorașe].", ["migrație", "sate"], "Urbanizare, megaorașe.")
    A.a(2, "3.4", "Ce oraș din România este capitala?", "București", ["Cluj-Napoca", "Iași", "Buzău"], "București e cel mai mare oraș al României.")
    A.a(2, "2.1", "Ce fel de așezare este Râmnicu Sărat?", "un oraș (municipiu) din județul Buzău", ["un sat de munte", "capitala județului", "o stațiune pe litoral"], "Reședința județului Buzău e municipiul Buzău.")
    A.a(3, "1.2", "Ce este o zonă metropolitană?", "un oraș mare împreună cu localitățile din jur, legate prin muncă și transport", ["un sat izolat", "un parc național", "o țară mică"], "Mulți oameni locuiesc în jurul orașului și fac naveta zilnic.")
    A.a(2, "1.1", "Ce înseamnă navetă?", "drumul zilnic între locuință și locul de muncă sau școală, din altă localitate", ["mutarea definitivă în altă țară", "o excursie de vacanță", "un tren de marfă"], "Navetiștii locuiesc într-o localitate și lucrează în alta.")
    A.g(3, "2.3 4.1", "Graficul arată proporția populației urbane în trei țări imaginare. Care e cea mai urbanizată?", grafic("bare", "Populația urbană (date imaginare)", [("țara A", 82), ("țara B", 35), ("țara C", 55)], "%"), "țara A", ["țara B", "țara C", "sunt egale"], "În țara A, 82 % din oameni trăiesc la oraș.")
    A.a(3, "4.3", "Compară un sat de munte cu un sat de câmpie.", "la munte casele sunt risipite și se cresc animale; la câmpie casele sunt adunate și se cultivă cereale", ["sunt identice", "la munte se cultivă orez", "la câmpie casele sunt pe stânci"], "Relieful decide forma și ocupațiile.")
    A.a(2, "3.3", "De ce în satele de la munte se cresc mai ales oi și vaci?", "pentru că acolo sunt pajiști bogate, dar terenul e prea înclinat pentru culturi mari", ["pentru că e cald tot anul", "pentru că sunt multe fabrici", "pentru că plouă puțin"], "Pășunile alpine sunt potrivite pentru animale.")
    A.d(2, "2.1", "Ce capitală europeană e marcată pe hartă?", "lume", 48.86, 2.35, "Paris", ["Londra", "Roma", "Madrid"], "Parisul e capitala Franței, pe Sena.")
    A.a(2, "4.2", "Ce clădiri și servicii găsești de obicei într-un oraș, dar rar într-un sat?", "spital mare, universitate, teatru, gară importantă", ["fântână", "grajd", "livadă"], "Orașele concentrează serviciile.")
    A.a(3, "3.2", "Ce înseamnă că un oraș „se extinde”?", "se construiesc cartiere noi la marginea lui, pe foste terenuri agricole", ["devine sat", "se mută în alt loc", "își pierde locuitorii"], "Extinderea orașelor consumă teren.")

    # ================================================================ S8 Resursele naturale
    R = Lectie(6, "VI-S08-resursele-naturale-valorificarea-acestora", "Resursele naturale și valorificarea lor",
               "Ce s-ar întâmpla dacă s-ar termina petrolul mâine?",
               [("Ce sunt resursele naturale", "Resursele naturale sunt bogățiile pe care oamenii le iau din natură și le folosesc: solul, apa, pădurile, mineralele, combustibilii, energia Soarelui și a vântului.\nResursele regenerabile se refac în timp scurt (apa, pădurile, dacă sunt folosite cu grijă) sau nu se termină (Soarele, vântul). Resursele neregenerabile se termină, pentru că s-au format în milioane de ani (petrolul, gazele naturale, cărbunele, minereurile)."),
                ("Tipuri de resurse", "Resurse energetice: petrol, gaze naturale, cărbune, uraniu, apă (hidrocentrale), vânt, Soare.\nResurse minerale: minereuri de fier, cupru, aur, aluminiu; sare; roci de construcție.\nResurse ale solului, apei și pădurilor: hrană, lemn, apă potabilă."),
                ("Folosirea durabilă", "Folosirea durabilă înseamnă să iei din natură atât cât se poate reface, ca resursele să ajungă și pentru generațiile viitoare.\nReciclarea, economisirea energiei și folosirea surselor regenerabile ajută la protejarea resurselor.")],
               stiaica="O doză de aluminiu poate fi reciclată de foarte multe ori, iar reciclarea consumă mult mai puțină energie decât producerea aluminiului nou din minereu.",
               ref=REF.format("Resursele naturale și valorificarea acestora"))
    R.a(1, "1.1", "Ce sunt resursele naturale?", "bogățiile luate din natură și folosite de oameni", ["obiectele fabricate", "banii unei țări", "clădirile"], "Apa, solul, pădurile, mineralele, combustibilii.")
    R.a(1, "1.1", "Ce înseamnă resursă regenerabilă?", "o resursă care se reface sau nu se termină", ["o resursă care se termină repede", "o resursă fabricată", "o resursă scumpă"], "Soarele, vântul, apa, pădurile folosite cu grijă.")
    R.a(1, "1.1", "Ce înseamnă resursă neregenerabilă?", "o resursă care se termină, pentru că s-a format în milioane de ani", ["o resursă care se reface într-un an", "energia Soarelui", "vântul"], "Petrolul, gazele, cărbunele.")
    R.s(2, "1.2", "Asociază resursa cu tipul ei.", [("energia Soarelui", "regenerabilă, inepuizabilă"), ("petrolul", "neregenerabilă, combustibil fosil"), ("pădurea", "regenerabilă, dacă e replantată"), ("minereul de fier", "neregenerabilă, resursă minerală")], "Combustibilii fosili și minereurile nu se refac.")
    R.s(2, "1.2", "Asociază resursa cu folosirea ei.", [("petrolul", "benzină și motorină"), ("minereul de fier", "oțel"), ("lemnul", "mobilă și hârtie"), ("sarea", "alimentație și industrie chimică")], "Resursele devin produse.")
    R.a(2, "3.2", "De ce petrolul e o resursă neregenerabilă?", "pentru că s-a format în milioane de ani din resturi de viețuitoare", ["pentru că e lichid", "pentru că e negru", "pentru că se găsește doar în mare"], "Îl consumăm mult mai repede decât se poate forma.")
    R.a(2, "1.1", "Cum se numesc combustibilii formați din resturi vechi de plante și animale?", "combustibili fosili", ["combustibili solari", "combustibili verzi", "combustibili de mare"], "Cărbunele, petrolul și gazele naturale sunt fosili.")
    R.a(2, "3.2", "Ce sursă de energie folosește o hidrocentrală?", "apa în mișcare", ["cărbunele", "vântul", "uraniul"], "Apa din lac curge prin turbine.")
    R.a(2, "3.2", "Ce sursă de energie folosesc panourile fotovoltaice?", "lumina Soarelui", ["vântul", "petrolul", "valurile"], "Panourile transformă lumina în electricitate.")
    R.a(2, "3.4", "Ce hidrocentrală mare din România e pe Dunăre?", "Porțile de Fier", ["Vidraru", "Bicaz", "Lotru"], "Porțile de Fier I e cea mai mare hidrocentrală din România.")
    R.a(2, "3.4", "Unde se află centrala nucleară a României?", "la Cernavodă", ["la Petroșani", "la Sibiu", "la Râmnicu Sărat"], "Centrala nucleară de la Cernavodă e în județul Constanța.")
    R.a(2, "2.1", "Ce resursă energetică se exploatează tradițional în Valea Jiului?", "cărbunele (huila)", ["petrolul", "aurul", "sarea"], "Valea Jiului a fost principalul bazin carbonifer al României.")
    R.a(2, "2.1", "Ce resursă s-a exploatat de foarte mult timp în Munții Apuseni?", "aurul", ["petrolul", "cărbunele", "uraniul"], "Roșia Montană e o veche zonă auriferă, cu galerii din epoca romană.")
    R.a(2, "2.1", "Ce resursă se exploata în salina de la Slănic (Prahova)?", "sarea", ["petrolul", "aurul", "cuprul"], "Salinele vechi sunt azi și atracții turistice.")
    R.a(2, "4.3", "Ce înseamnă folosirea durabilă a resurselor?", "să iei din natură atât cât se poate reface, ca să ajungă și pentru viitor", ["să consumi tot cât mai repede", "să nu folosești nicio resursă", "să arunci resursele"], "Grija pentru generațiile viitoare.")
    R.a(2, "4.3", "Ce poți face ca să economisești resurse acasă?", "stingi lumina când ieși din cameră și reciclezi", ["lași aparatele pornite", "arunci tot la un loc", "folosești mereu pungi noi"], "Economia de energie și reciclarea ajută.")
    R.o(2, "3.2", "Ordonează drumul unei doze de aluminiu reciclate.", ["arunci doza la containerul galben", "dozele sunt colectate", "sunt topite la fabrică", "din aluminiu se fac doze noi"], "Reciclarea", "Colectare, topire, produs nou.")
    R.adev(2, "1.2", "Pădurile sunt o resursă regenerabilă doar dacă sunt replantate și nu sunt tăiate mai repede decât cresc.", True, "Adevărat: folosirea cu grijă păstrează pădurea.")
    R.adev(1, "1.2", "Vântul se poate termina dacă îl folosim prea mult.", False, "Fals: vântul e o resursă inepuizabilă.")
    R.l(2, "1.1", "Completează.", "Petrolul și cărbunele sunt resurse [neregenerabile], iar Soarele și vântul sunt resurse [regenerabile].", ["fabricate", "rare"], "Fosile – neregenerabile; Soare, vânt – regenerabile.")
    R.l(2, "3.2", "Completează.", "Centralele care folosesc vântul se numesc centrale [eoliene]; cele care folosesc apa se numesc [hidrocentrale].", ["nucleare", "termocentrale"], "Eolian = de la vânt (Eol, zeul vântului).")
    R.g(3, "2.3 4.1", "Graficul arată din ce surse produce energie o țară imaginară. Ce sursă e cea mai importantă?", grafic("structura", "Producția de electricitate (țară imaginară)", [("hidro", 30), ("nuclear", 20), ("cărbune", 15), ("gaze", 15), ("vânt și Soare", 20)], "%"), "hidroenergia", ["cărbunele", "gazele", "nuclearul"], "Hidroenergia are cea mai mare parte: 30 %.")
    R.a(2, "2.1", "Ce țară din Orientul Mijlociu are rezerve uriașe de petrol?", "Arabia Saudită", ["Elveția", "Islanda", "Portugalia"], "Golful Persic are mari rezerve de petrol.")
    R.p(3, "2.1", "Atinge pe hartă zona Golfului Persic, bogată în petrol.", "lume", 27, 51, "Golful Persic", 600, "Golful Persic e între Peninsula Arabia și Iran.")
    R.a(3, "3.2", "De ce parcurile eoliene se construiesc des în Dobrogea?", "pentru că acolo bate des vânt puternic, iar terenul e deschis", ["pentru că acolo e mult cărbune", "pentru că acolo sunt munți înalți", "pentru că plouă mult"], "Vântul constant face eolienele eficiente.")
    R.a(2, "3.2", "Ce resursă e baza agriculturii?", "solul fertil (și apa)", ["petrolul", "aurul", "uraniul"], "Fără sol fertil nu există recolte bune.")
    R.a(3, "1.2", "Ce problemă apare când o țară depinde de o singură resursă, de exemplu petrolul?", "când prețul petrolului scade sau rezervele se termină, economia are de suferit", ["nu apare nicio problemă", "țara devine mai rece", "țara pierde pădurile automat"], "Diversificarea economiei e mai sigură.")
    R.a(2, "4.2", "Ce culoare are, de obicei, containerul pentru hârtie și carton, în România?", "albastru", ["galben", "verde", "roșu"], "Albastru – hârtie; galben – plastic și metal; verde – sticlă.")
    R.d(2, "2.1", "Ce țară bogată în petrol și gaze din nordul Europei e marcată pe hartă?", "lume", 62, 9, "Norvegia", ["Suedia", "Finlanda", "Islanda"], "Norvegia exploatează petrol și gaze din Marea Nordului.")
    R.a(3, "3.3", "Ce înseamnă „economie circulară”?", "produsele sunt folosite mai mult timp, reparate și reciclate, în loc să fie aruncate", ["mașinile merg în cerc", "fabricile sunt rotunde", "se aruncă tot după o folosire"], "Deșeurile devin resurse.")

    # ================================================================ S9 Activitățile economice
    D = Lectie(6, "VI-S09-domeniile-activitatilor-economice-terra", "Domeniile activităților economice: agricultura, industria, serviciile",
               "Câți oameni lucrează ca să ajungă o pâine pe masa ta?",
               [("Agricultura", "Agricultura cuprinde cultivarea plantelor și creșterea animalelor. Produce hrană și materii prime pentru industrie (bumbac, lână, sfeclă de zahăr).\nCulturile depind de climă și sol: grâul și porumbul în zona temperată, orezul în Asia musonică, cafeaua și cacaoa în zona caldă."),
                ("Industria", "Industria transformă materiile prime în produse: industria extractivă scoate resursele din pământ; industria prelucrătoare face din ele produse (metalurgie, construcții de mașini, industrie chimică, alimentară, textilă, electronică).\nEnergia electrică e produsă în centrale: termocentrale, hidrocentrale, centrale nucleare, eoliene, solare."),
                ("Serviciile", "Serviciile sunt activități care nu produc obiecte, ci ajută oamenii: transporturile, comerțul, educația, sănătatea, turismul, băncile, comunicațiile, IT.\nÎn țările dezvoltate, cei mai mulți oameni lucrează în servicii.")],
               stiaica="Orezul e hrana de bază pentru mai mult de jumătate din populația lumii, mai ales în Asia.",
               ref=REF.format("Domeniile activităților economice pe Terra"))
    D.s(1, "1.1", "Asociază ocupația cu domeniul economic.", [("fermierul", "agricultură"), ("muncitorul din fabrica de mașini", "industrie"), ("profesorul", "servicii – educație"), ("medicul", "servicii – sănătate")], "Trei mari domenii: agricultură, industrie, servicii.")
    D.a(1, "1.1", "Ce cuprinde agricultura?", "cultivarea plantelor și creșterea animalelor", ["fabricarea mașinilor", "transportul cu avionul", "băncile"], "Agricultura produce hrană.")
    D.a(1, "1.1", "Ce face industria?", "transformă materiile prime în produse", ["cultivă plante", "predă la școală", "transportă turiști"], "Industria fabrică produse.")
    D.a(1, "1.1", "Ce sunt serviciile?", "activități care ajută oamenii, fără să producă obiecte (transport, comerț, educație, sănătate)", ["cultivarea grâului", "extragerea cărbunelui", "fabricarea oțelului"], "Serviciile sunt cel mai mare domeniu în țările dezvoltate.")
    D.s(2, "3.2", "Asociază planta cultivată cu zona potrivită.", [("orezul", "Asia musonică, cu ploi multe"), ("grâul", "câmpiile din zona temperată"), ("cafeaua", "zona caldă, pe podișuri"), ("măslinul", "zona mediteraneeană")], "Clima decide culturile.")
    D.a(2, "3.2", "Ce cultură e hrana de bază pentru mulți oameni din Asia?", "orezul", ["cartoful", "ovăzul", "secara"], "Orezul are nevoie de căldură și multă apă.")
    D.a(2, "2.1", "Ce țară e cel mai mare producător de cafea?", "Brazilia", ["Norvegia", "Canada", "Egipt"], "Brazilia are climă caldă și podișuri potrivite.")
    D.a(2, "1.2", "Ce înseamnă industria extractivă?", "scoaterea resurselor din pământ (cărbune, petrol, minereuri)", ["fabricarea hainelor", "construirea de mașini", "vânzarea în magazine"], "Extragere = scoatere.")
    D.s(2, "1.2", "Asociază ramura industriei cu produsul.", [("industria alimentară", "pâine, lapte, conserve"), ("industria textilă", "țesături și haine"), ("industria construcțiilor de mașini", "automobile, tractoare"), ("industria chimică", "medicamente, îngrășăminte")], "Ramurile industriei.")
    D.o(2, "3.2", "Ordonează drumul pâinii de la câmp la masă.", ["fermierul seamănă grâul", "grâul e recoltat", "la moară se face făina", "la brutărie se coace pâinea", "pâinea e vândută în magazin"], "De la câmp la masă", "Agricultură → industrie → servicii (comerț).")
    D.a(2, "3.2", "În drumul pâinii, ce etapă ține de servicii?", "vânzarea în magazin și transportul", ["semănatul", "măcinatul", "recoltarea"], "Comerțul și transportul sunt servicii.")
    D.a(2, "3.4", "Ce fabrică de automobile cunoscută are România la Mioveni?", "Dacia", ["Volvo", "Ferrari", "Toyota"], "Uzina Dacia de la Mioveni (județul Argeș).")
    D.a(2, "1.1", "Ce înseamnă turism?", "călătoria oamenilor pentru odihnă, cunoaștere sau distracție, în alt loc decât cel în care locuiesc", ["lucrul la fabrică", "cultivarea viei", "construirea drumurilor"], "Turismul e un serviciu important.")
    D.s(2, "3.2", "Asociază mijlocul de transport cu caracteristica lui.", [("avionul", "cel mai rapid pe distanțe mari"), ("vaporul", "cel mai potrivit pentru mărfuri grele, pe mare"), ("trenul", "mulți pasageri și mărfuri pe uscat"), ("conducta", "petrol și gaze")], "Fiecare transport are avantajele lui.")
    D.a(2, "1.2", "În ce domeniu lucrează majoritatea oamenilor în țările dezvoltate?", "în servicii", ["în agricultură", "în mine", "în pescuit"], "În țările dezvoltate, agricultura folosește puțini oameni, dar cu mașini moderne.")
    D.adev(2, "1.2", "Agricultura dă materii prime și pentru industrie.", True, "Adevărat: bumbacul, lâna, sfecla de zahăr ajung în fabrici.")
    D.adev(2, "1.2", "Serviciile produc obiecte, ca mașinile și hainele.", False, "Fals: obiectele le produce industria; serviciile ajută oamenii.")
    D.l(2, "1.1", "Completează.", "Cultivarea plantelor și creșterea animalelor formează [agricultura]; transformarea materiilor prime în produse se numește [industrie].", ["turism", "comerț"], "Agricultură și industrie.")
    D.l(2, "3.2", "Completează.", "Transportul, comerțul, educația și sănătatea sunt [servicii].", ["industrii", "culturi"], "Activități care ajută oamenii.")
    D.g(3, "2.3 4.1", "Graficul arată în ce domenii lucrează oamenii dintr-o țară imaginară. Unde lucrează cei mai mulți?", grafic("structura", "Populația ocupată pe domenii (țară imaginară)", [("agricultură", 10), ("industrie", 25), ("servicii", 65)], "%"), "în servicii", ["în agricultură", "în industrie", "egal"], "65 % din oameni lucrează în servicii.")
    D.g(3, "2.3 4.3 4.1", "Compară: țara imaginară X are 45 % din oameni în agricultură, iar țara Y doar 3 %. Ce poți presupune?", grafic("bare", "Populația ocupată în agricultură (țări imaginare)", [("țara X", 45), ("țara Y", 3)], "%"), "țara Y are agricultură foarte mecanizată și o economie bazată pe servicii", ["țara X are mai multe fabrici", "țara Y nu are hrană", "sunt la fel de dezvoltate"], "Puțini agricultori cu multe mașini pot produce multă hrană.")
    D.a(2, "3.2", "De ce creșterea oilor e frecventă la munte?", "pentru că acolo sunt pășuni întinse", ["pentru că acolo sunt fabrici", "pentru că e cald tot anul", "pentru că sunt multe orașe"], "Transhumanța e o tradiție în Carpați.")
    D.a(2, "4.3", "Prin ce se deosebește o fermă modernă de una tradițională?", "folosește mașini, irigații și tehnologie, cu mai puțini oameni", ["are mai mulți cai", "nu folosește apă", "nu produce nimic"], "Mecanizarea crește producția.")
    D.a(3, "3.2", "De ce multe fabrici se construiesc lângă porturi sau căi ferate?", "ca materiile prime și produsele să fie transportate ușor", ["pentru că e mai frumos", "pentru că acolo e mai frig", "pentru că nu e voie altundeva"], "Transportul ieftin e important pentru industrie.")
    D.a(2, "3.3", "Ce înseamnă agricultura ecologică?", "agricultura fără pesticide și îngrășăminte chimice de sinteză", ["agricultura doar cu mașini", "agricultura în deșert", "agricultura pe acoperiș obligatoriu"], "Produsele ecologice au o etichetă specială.")
    D.a(2, "2.1", "În ce zonă a României se cultivă cel mai mult grâu și porumb?", "în Câmpia Română", ["în Munții Făgăraș", "în Delta Dunării", "în Munții Apuseni"], "Câmpia Română are soluri fertile și relief plan.")
    D.a(3, "1.2", "De ce IT-ul (informatica) e considerat un serviciu?", "pentru că oferă programe, aplicații și comunicare, nu obiecte fizice", ["pentru că produce oțel", "pentru că se face pe câmp", "pentru că e o ramură a agriculturii"], "Serviciile digitale cresc foarte mult.")
    D.p(2, "2.1", "Atinge pe hartă Brazilia, cel mai mare producător de cafea.", "lume", -12, -50, "Brazilia", 1500, "Brazilia e în estul Americii de Sud.")
    D.a(2, "1.1", "Ce înseamnă „materie primă”?", "materialul din care industria face produse (lemn, minereu, bumbac, lapte)", ["produsul gata de vânzare", "un magazin", "un mijloc de transport"], "Materia primă se transformă în fabrici.")
    D.a(2, "4.2", "Ce domeniu economic e principal în stațiunile de pe litoral?", "turismul", ["mineritul", "metalurgia", "silvicultura"], "Hoteluri, restaurante, plaje.")

    # ================================================================ S10 Efectele activităților umane
    F = Lectie(6, "VI-S10-efectele-activitatilor-umane-asupra", "Efectele activităților umane asupra mediului",
               "Unde ajunge o sticlă de plastic aruncată pe stradă?",
               [("Cum schimbă oamenii mediul", "Activitățile oamenilor schimbă natura: pădurile sunt tăiate pentru lemn și terenuri agricole, râurile sunt îndiguite, se construiesc orașe și drumuri, se extrag resurse.\nUnele schimbări sunt utile (hrană, energie, locuințe), dar multe aduc probleme: poluarea aerului, a apei și a solului, pierderea de habitate și de specii."),
                ("Tipuri de poluare", "Poluarea aerului: fum de la fabrici, mașini, arderea deșeurilor. Poluarea apei: ape uzate netratate, deșeuri, petrol. Poluarea solului: deșeuri, pesticide, îngrășăminte în exces. Există și poluare fonică (zgomot) și luminoasă.\nGazele cu efect de seră din arderea combustibililor fosili contribuie la încălzirea climei."),
                ("Calitatea vieții și soluțiile", "Calitatea vieții înseamnă cât de bine trăiesc oamenii: aer și apă curate, hrană sănătoasă, locuință, educație, sănătate, spații verzi, siguranță.\nSoluții: reciclarea, energia regenerabilă, transportul public, plantarea copacilor, arii protejate, legi de protecție a mediului.")],
               stiaica="O sticlă de plastic aruncată în natură se descompune foarte greu, în sute de ani, și se rupe în bucăți tot mai mici, numite microplastice.",
               ref=REF.format("Efectele activităților umane asupra mediului și calitatea vieții"))
    F.a(1, "1.1", "Ce este poluarea?", "murdărirea aerului, apei sau solului cu substanțe dăunătoare", ["plantarea copacilor", "curățarea parcului", "reciclarea"], "Poluarea dăunează oamenilor și naturii.")
    F.s(2, "1.2", "Asociază tipul de poluare cu sursa.", [("poluarea aerului", "fumul de la fabrici și mașini"), ("poluarea apei", "apele uzate netratate"), ("poluarea solului", "deșeurile și pesticidele"), ("poluarea fonică", "zgomotul traficului")], "Surse diferite de poluare.")
    F.a(2, "1.2", "Ce înseamnă defrișare?", "tăierea pădurilor", ["plantarea pădurilor", "irigarea câmpurilor", "construirea de baraje"], "Defrișările reduc habitatele și favorizează eroziunea.")
    F.a(2, "3.2", "Ce urmări are defrișarea pe versanți?", "eroziunea solului, alunecări de teren și inundații", ["mai mult oxigen", "soluri mai fertile", "mai puține inundații"], "Fără rădăcini, solul e spălat de ploi.")
    F.a(2, "3.2", "Ce produce efectul de seră accentuat de om?", "gazele din arderea combustibililor fosili (cărbune, petrol, gaze)", ["plantarea copacilor", "energia solară", "reciclarea"], "Dioxidul de carbon reține căldura în atmosferă.")
    F.a(2, "1.1", "Ce sunt microplasticele?", "bucăți foarte mici de plastic, rezultate din ruperea deșeurilor", ["plante mici din mare", "un tip de nisip", "insecte"], "Microplasticele ajung în apă, sol și chiar în hrană.")
    F.a(2, "1.1", "Ce înseamnă calitatea vieții?", "cât de bine trăiesc oamenii: aer curat, sănătate, educație, locuință, siguranță", ["cât de mare e țara", "câte mașini are un oraș", "înălțimea clădirilor"], "Calitatea vieții depinde și de mediu.")
    F.a(2, "4.3", "Ce poți face pentru mediu în fiecare zi?", "colectezi selectiv deșeurile și folosești sacoșe refolosibile", ["arunci plasticul în râu", "arzi frunzele", "lași lumina aprinsă"], "Obiceiurile mici contează.")
    F.s(2, "4.3", "Asociază problema cu o soluție.", [("aer poluat în oraș", "transport public, biciclete, parcuri"), ("deșeuri multe", "reciclare și compost"), ("ape murdare", "stații de epurare"), ("păduri tăiate", "replantare și arii protejate")], "Pentru fiecare problemă există soluții.")
    F.a(2, "1.1", "Ce este o stație de epurare?", "o instalație care curăță apele uzate înainte să ajungă în râu", ["o fabrică de apă minerală", "o hidrocentrală", "o fântână"], "Epurarea protejează râurile.")
    F.o(3, "1.2", "Ordonează drumul unei sticle de plastic aruncate pe stradă.", ["sticla e aruncată pe stradă", "ploaia o duce în canal", "ajunge în râu", "râul o duce în mare", "se rupe în microplastice"], "Drumul deșeului", "De la stradă la ocean.")
    F.adev(2, "1.2", "Toate efectele activităților umane asupra mediului sunt negative.", False, "Fals: unele sunt pozitive (parcuri, replantări, arii protejate).")
    F.adev(2, "3.2", "Zgomotul puternic și constant este o formă de poluare.", True, "Adevărat: poluarea fonică afectează somnul și sănătatea.")
    F.l(2, "1.1", "Completează.", "Tăierea pădurilor se numește [defrișare]; murdărirea mediului se numește [poluare].", ["reciclare", "irigare"], "Defrișare, poluare.")
    F.l(2, "4.3", "Completează.", "Plasticul și metalul se pun în containerul [galben], iar sticla în containerul [verde].", ["albastru", "roșu"], "Galben – plastic și metal; verde – sticlă; albastru – hârtie.")
    F.g(3, "2.3 4.1", "Graficul arată cantitatea de deșeuri reciclate într-o școală imaginară, pe luni. Ce observi?", grafic("bare", "Deșeuri reciclate la o școală imaginară", [("sept.", 20), ("oct.", 35), ("nov.", 50), ("dec.", 60)], "kg"), "cantitatea reciclată a crescut în fiecare lună", ["a scăzut", "a rămas la fel", "s-a reciclat doar în septembrie"], "De la 20 kg la 60 kg.")
    F.a(2, "3.2", "De ce aerul e mai poluat în orașele mari?", "din cauza traficului intens, a fabricilor și a încălzirii clădirilor", ["din cauza parcurilor", "din cauza râurilor", "din cauza păsărilor"], "Arderea combustibililor poluează aerul.")
    F.a(3, "3.2", "Ce legătură e între poluare și sănătate?", "aerul și apa poluate pot produce boli ale plămânilor, ale inimii și altele", ["nu există nicio legătură", "poluarea face oamenii mai sănătoși", "doar animalele sunt afectate"], "Mediul curat înseamnă oameni mai sănătoși.")
    F.a(2, "1.2", "Ce este poluarea luminoasă?", "prea multă lumină artificială noaptea, care ascunde stelele și deranjează animalele", ["lumina Soarelui ziua", "lumina lunii", "fulgerele"], "Iluminatul excesiv afectează păsările și insectele.")
    F.a(2, "3.3", "Ce sunt spațiile verzi și de ce sunt importante în oraș?", "parcuri și grădini care curăță aerul, răcoresc vara și sunt locuri de odihnă", ["parcări", "fabrici", "magazine"], "Spațiile verzi cresc calitatea vieții.")
    F.a(3, "4.3", "Compară mașina cu benzină și bicicleta pentru un drum de 3 km.", "bicicleta nu poluează și e sănătoasă; mașina poluează și consumă combustibil", ["sunt la fel de poluante", "bicicleta poluează mai mult", "mașina nu poluează"], "Pe distanțe mici, bicicleta sau mersul pe jos sunt mai bune.")
    F.a(2, "3.2", "Ce se întâmplă când un râu e poluat cu petrol?", "peștii și păsările mor, iar apa nu mai poate fi folosită", ["râul devine mai curat", "peștii cresc mai repede", "nu se întâmplă nimic"], "Petrolul formează o peliculă care împiedică oxigenul.")
    F.a(2, "4.2", "Ce face o arie protejată?", "păstrează natura nealterată, cu reguli stricte de vizitare", ["permite construcția de fabrici", "permite vânatul liber", "e un parc de distracții"], "Parcurile naționale protejează natura.")
    F.a(3, "1.2", "De ce încălzirea climei e o problemă pentru toată lumea?", "aduce valuri de căldură, secete, topirea ghețarilor și creșterea nivelului mării", ["face iernile mai lungi peste tot", "nu are efecte", "afectează doar Antarctica"], "Schimbările climatice afectează toate continentele.")
    F.a(2, "4.3", "Cum ajută energia solară mediul?", "produce electricitate fără fum și fără gaze cu efect de seră", ["produce fum negru", "taie pădurile", "poluează râurile"], "Energia regenerabilă e mai curată.")
    F.a(2, "3.2", "Ce sunt deșeurile periculoase din casă care nu se aruncă la gunoi?", "bateriile, becurile cu mercur, medicamentele expirate", ["cojile de fructe", "hârtia", "frunzele"], "Se duc la puncte speciale de colectare.")
    F.d(3, "2.1", "Pădurea marcată pe hartă e amenințată de defrișări. Care e?", "lume", -4, -62, "pădurea amazoniană", ["taigaua siberiană", "Pădurea Neagră", "pădurea Congo"], "Amazonia, în America de Sud, pierde suprafețe mari prin defrișări.")
    F.a(2, "1.2", "Ce sunt gropile de gunoi ecologice?", "depozite amenajate ca deșeurile să nu polueze solul și apa", ["râuri cu gunoaie", "păduri", "câmpuri cultivate"], "Depozitele ecologice au straturi impermeabile.")
    F.a(2, "4.3", "Ce poate face clasa ta pentru mediul școlii?", "un concurs de colectare selectivă și plantarea de flori pentru albine", ["vopsirea copacilor", "aruncarea gunoiului peste gard", "tăierea gardului viu"], "Proiectele mici dau rezultate mari.")
    F.a(3, "3.3", "Ce înseamnă „dezvoltare durabilă”?", "dezvoltare care satisface nevoile de azi fără să le strice pe cele ale generațiilor viitoare", ["dezvoltare cât mai rapidă cu orice preț", "oprirea oricărei dezvoltări", "construirea doar de clădiri înalte"], "Echilibru între economie, oameni și natură.")

    # ================================================================ S12 Expediție: orizontul local
    E = Expeditie(6, "VI-S12-aplicatii-practice-analiza-interpretarea", "Expediție: oamenii și locurile din orizontul meu",
                  "Cum s-a schimbat orașul tău în ultimii 30 de ani?",
                  ref=REF.format("Aplicații practice: Analiza și interpretarea caracteristicilor demografice și de locuire din orizontul local"))
    E.a(1, "4.1", "Ce instituție publică datele oficiale despre populația României?", "Institutul Național de Statistică (INS)", ["Agenția Spațială Română", "Poliția", "Banca Națională"], "INS face recensămintele și publică statistici.")
    E.pas("1. Datele oficiale", "Cu ajutorul profesorului, caută pe site-ul INS (sau în broșura primăriei) populația orașului Râmnicu Sărat la ultimele două recensăminte (2011 și 2021).",
          jurnal="Notează cele două valori și calculează dacă populația a crescut sau a scăzut și cu cât.")
    E.a(2, "4.2", "Populația unui oraș imaginar a scăzut de la 38 000 la 33 000 de locuitori. Cu cât a scăzut?", "cu 5 000 de locuitori", ["cu 71 000", "cu 500", "cu 3 300"], "38 000 − 33 000 = 5 000.")
    E.a(2, "4.2", "Ce motive pot explica scăderea populației unui oraș mic?", "plecarea tinerilor la studii și muncă și natalitatea scăzută", ["prea mulți copii născuți", "construirea unei universități", "creșterea locurilor de muncă"], "Migrația și sporul natural negativ reduc populația.")
    E.pas("2. Interviul", "Întreabă un bunic sau un vecin în vârstă cum arăta cartierul tău când era copil: ce clădiri, magazine, fabrici, drumuri erau.",
          jurnal="Scrie 3 lucruri care s-au schimbat și 1 lucru care a rămas la fel.")
    E.a(3, "4.1", "Faci o hartă a cartierului. Ce semne convenționale pui în legendă?", "școală, spital, parc, magazin, stație de autobuz", ["nume de colegi", "temperaturi", "înălțimi de munți"], "Legenda explică semnele hărții.")
    E.pas("3. Harta cartierului", "Desenează harta simplă a drumului de acasă la școală, cu legendă: clădiri importante, parcuri, străzi principale.",
          jurnal="Fotografiază harta.", foto=True)
    E.pas("4. O provocare locală", "Alege o problemă a orașului (trafic, spații verzi, deșeuri, locuri de joacă) și propune o soluție realistă.",
          jurnal="Scrie problema, de ce e importantă și soluția ta, în 4–5 rânduri.")

    return Unitate(6, "u2-antroposfera.json", "Antroposfera – omul și activitățile umane").add(P, A, R, D, F, E)
